import{_ as e,o,c as a,a2 as n}from"./chunks/framework.B7YvHKtj.js";const p=JSON.parse('{"title":"","titleTemplate":false,"description":"","frontmatter":{"layout":"home","titleTemplate":false,"hero":{"name":"CoWatcher Documentation","text":"User Guides & Language Immersion Knowledge Base","tagline":"No deep technical background required. Master bilingual subtitles, watch history tracking, and vocabulary flashcards with ease.","image":{"src":"/icons/icon128.png","alt":"CoWatcher Logo"},"actions":[{"theme":"brand","text":"3-Minute Quickstart","link":"/en/docs/quickstart"},{"theme":"alt","text":"Shortcuts & Controls","link":"/en/docs/guide/popup"},{"theme":"alt","text":"Official Showcase ↗","link":"/en/"}]},"features":[{"icon":"🚀","title":"Quickstart & Hotkeys","details":"Install the extension, toggle subtitles anytime with Alt + T, swap primary/secondary layers, and inspect words.","link":"/en/docs/quickstart"},{"icon":"🎬","title":"Supported Platforms","details":"Practical guides for Netflix (ad drift guard), TVer Japan (fullscreen mounting), and YouTube dual tracks.","link":"/en/docs/platforms/netflix"},{"icon":"🤖","title":"Choosing Your AI Provider","details":"Free built-in translation, zero-cost private local Ollama (GPU), or cutting-edge cloud models (DeepSeek, Claude, Gemini).","link":"/en/docs/providers/openrouter"},{"icon":"📝","title":"Watch History & Flashcards","details":"Automatically record viewing history and duration, retain character names across episodes, and export to Anki.","link":"/en/docs/guide/popup"},{"icon":"⚙️","title":"Advanced Pipeline Tuning","details":"Dual-model collaborative flow, refill thresholds, lookahead windows, and synchronization offsets for power users.","link":"/en/docs/advanced/dual_model"},{"icon":"🌟","title":"Contributors & Sponsors","details":"Browse our honor roll of code contributors, translators, and coffee sponsors, and learn how to contribute.","link":"https://github.com/cowatcher-app/cowatcher-extension/blob/main/CONTRIBUTORS.md"}]},"headers":[],"relativePath":"en/docs/index.md","filePath":"en/docs/index.md"}'),i={name:"en/docs/index.md"};function l(r,t,s,c,d,u){return o(),a("div",null,[...t[0]||(t[0]=[n('<h2 id="🧭-documentation-hub" tabindex="-1">🧭 Documentation Hub <a class="header-anchor" href="#🧭-documentation-hub" aria-label="Permalink to &quot;🧭 Documentation Hub&quot;">​</a></h2><h3 id="_1-🌟-which-translation-provider-should-i-choose" tabindex="-1">1. 🌟 Which Translation Provider Should I Choose? <a class="header-anchor" href="#_1-🌟-which-translation-provider-should-i-choose" aria-label="Permalink to &quot;1. 🌟 Which Translation Provider Should I Choose?&quot;">​</a></h3><p>CoWatcher supports multiple translation providers to suit high school language learners and seasoned developers alike:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Option</th><th style="text-align:left;">Best For</th><th style="text-align:left;">Cost</th><th style="text-align:left;">Key Highlights</th><th style="text-align:left;">Setup Effort</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Free Built-in Translation</strong></td><td style="text-align:left;">Casual viewers &amp; language learners</td><td style="text-align:left;"><strong>100% Free</strong></td><td style="text-align:left;">Ready out of the box with zero extra configuration</td><td style="text-align:left;">⭐ Zero setup</td></tr><tr><td style="text-align:left;"><strong>Local GPU (Ollama)</strong></td><td style="text-align:left;">Users with dedicated GPUs (GTX 1660 / RTX 2060+)</td><td style="text-align:left;"><strong>100% Free</strong></td><td style="text-align:left;">100% private, no internet bandwidth, low latency</td><td style="text-align:left;">⭐⭐ Requires Ollama</td></tr><tr><td style="text-align:left;"><strong>Top Cloud Models (OpenRouter)</strong></td><td style="text-align:left;">High-accuracy movie translation &amp; slang consistency</td><td style="text-align:left;">Pay-per-use (fractions of a cent)</td><td style="text-align:left;">Connects DeepSeek, Claude, Gemini, etc.</td><td style="text-align:left;">⭐⭐ Requires API Key</td></tr></tbody></table><ul><li><a href="/cowatcher-extension-public/en/docs/providers/ollama.html">👉 Ollama Local Deployment Guide</a></li><li><a href="/cowatcher-extension-public/en/docs/providers/openrouter.html">👉 OpenRouter Cloud API Guide</a></li></ul><hr><h3 id="_2-⚡-common-shortcuts-quick-actions" tabindex="-1">2. ⚡ Common Shortcuts &amp; Quick Actions <a class="header-anchor" href="#_2-⚡-common-shortcuts-quick-actions" aria-label="Permalink to &quot;2. ⚡ Common Shortcuts &amp; Quick Actions&quot;">​</a></h3><p>While watching your favorite shows, you only need to know a few essential controls:</p><ul><li><p><strong><code>Alt + T</code></strong>: Global hotkey to toggle AI bilingual subtitles on or off instantly.</p></li><li><p><strong>Swap Primary/Secondary Subtitles</strong>: Toggle in the popup to place translated text on top or bottom according to your learning preferences.</p></li><li><p><strong>Instant Word Definition</strong>: Click or hover any unfamiliar term to view meanings and save directly to your Anki study deck.</p></li><li><p><strong>Cross-Episode Character Memory</strong>: Character aliases discovered in Episode 1 persist into Episode 2 and beyond automatically.</p></li><li><p><a href="/cowatcher-extension-public/en/docs/guide/popup.html">👉 Read Full Popup &amp; Shortcuts Guide</a></p></li></ul><hr><h3 id="_3-📺-platform-playbooks" tabindex="-1">3. 📺 Platform Playbooks <a class="header-anchor" href="#_3-📺-platform-playbooks" aria-label="Permalink to &quot;3. 📺 Platform Playbooks&quot;">​</a></h3><ul><li><a href="/cowatcher-extension-public/en/docs/platforms/netflix.html">Netflix Deep Integration &amp; Ad Drift Guard</a></li><li><a href="/cowatcher-extension-public/en/docs/platforms/tver.html">TVer Japan Player Fullscreen Mounting</a></li><li><a href="/cowatcher-extension-public/en/docs/platforms/youtube.html">YouTube Bilingual Subtitles &amp; Audio Track Ingestion</a></li></ul><hr><h3 id="_4-💖-acknowledgements-community" tabindex="-1">4. 💖 Acknowledgements &amp; Community <a class="header-anchor" href="#_4-💖-acknowledgements-community" aria-label="Permalink to &quot;4. 💖 Acknowledgements &amp; Community&quot;">​</a></h3><p>CoWatcher is 100% open-source. Check out our <a href="/cowatcher-extension-public/en/docs/architecture.html">System Architecture Whitepaper</a>, submit an issue or PR on <a href="https://github.com/cowatcher-app/cowatcher-extension" target="_blank" rel="noreferrer">GitHub</a>, and view the <a href="https://github.com/cowatcher-app/cowatcher-extension/blob/main/CONTRIBUTORS.md" target="_blank" rel="noreferrer">Contributors &amp; Sponsors Roll</a>!</p>',15)])])}const m=e(i,[["render",l]]);export{p as __pageData,m as default};
